------------------------------------------------------- public

function UIActivityTimeLimitedTaskPanel:Refresh(activityDojo)
    self.activityDt   = activityDojo
    GameUtils.Request(Interfaces.ActivityTimeLimitedTaskLogin, {activityUuid = self:GetActivityId()},
            function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local data = response.data

                    self.taskData     = checkTable(data.activityTask)
                    self.taskConf     = checkTable(data.activityTaskConf)

                    -- init data
                    self:InitRewardsDt()
                    -- init event
                    self:InitBindEvent()
                    -- update view
                    self:InitView()
                    -- update topBar
                    self:RefreshCurrencyBarInfo()
                end
            end
    )
end

function UIActivityTimeLimitedTaskPanel:SetEnabled(enabled)
    local mask = self.LoopListCell.transform:Find("ParticleMask")
    if isNull(mask) then return end
        
    CfUtils.SetActive(mask, enabled)
end

function UIActivityTimeLimitedTaskPanel:RefreshCurrencyBarInfo()
    ActivityUtils.RefreshNavigatorGoods(self:GetTaskConf().itemId)
end

function UIActivityTimeLimitedTaskPanel:InitRewardsDt()
    self.canTaskMap = {}
    for _, taskDt in pairs(self:GetTaskDt()) do
        if taskDt.status == Constants.GetStatus.Can then
            self.canTaskMap[checkInt(taskDt.taskId)] = true
        end
    end

    table.sort(self:GetTaskDt(), function(a, b)
        local aStatus = checkInt(a.status)
        local bStatus = checkInt(b.status)
        if aStatus ~= bStatus then
            if aStatus == Constants.GetStatus.Can or bStatus == Constants.GetStatus.Can then
                return aStatus == Constants.GetStatus.Can
            else
                return aStatus < bStatus
            end
        else
            return checkInt(a.taskId) < checkInt(b.taskId)
        end
    end)

    ActivityUtils.UpdateActivityMainRedPointState(self:GetActivityId(), next(self:GetCanIdMap()) == nil and -1 or 0)
end

function UIActivityTimeLimitedTaskPanel:InitBindEvent()
    SetButtonAction(self.FontStyleButton, function ()
        if next(self:GetCanIdMap()) == nil then
            GameUtils.Toast(localize("暂无可领取的奖励"))
        else
            self:OnDrawTask()
        end
    end)
    SetButtonAction(self.TxtPlayState, function()
        if self:GetRuleId() > 0 then
            CfUtils.ShowModuleToast(self:GetRuleId())
        end
    end)
end

function UIActivityTimeLimitedTaskPanel:InitView()
    -- update reward
    self:RefreshReward()

    -- update view
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(self.activityDt.startTime, self.activityDt.endTime))
    CfUtils.FillText(self.Text, string.trim(self.activityDt.detail) ~= "" and self.activityDt.detail or "TO BE CONTINUE")

    local titleImgUrl = checkString(self.activityDt.titleImage)
    if string.len(titleImgUrl) > 0 then
        CfUtils.FillWebRawImage(self.ImgTitleName, titleImgUrl)
    end

    CfUtils.SetActive(self.TxtPlayState, checkInt(self:GetTaskConf().ruleId) > 0)

    local catBallId = checkInt(self:GetTaskConf().catBallId)
    CfUtils.SetActive(self.ImgCatball, catBallId > 0)
    if catBallId > 0 then
        local CatBallUtils = import("Game.CatBall.CatBallUtils")
        local catBallVo = CatBallUtils.GetCatBallVo(catBallId)
        CfUtils.FillImage(self.ImgCatball, catBallVo.picture)
    end
end

function UIActivityTimeLimitedTaskPanel:RefreshReward()
    if next(self:GetTaskDt()) == nil then return end

    -- update list
    local totalCount  = #self:GetTaskDt()
    local normalCount = totalCount

    if not self.LoopListCell.IsListViewInit then
        self.LoopListCell:InitListView(normalCount, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopListCell, normalCount)
    end
end

----------------------------------------------------------------------------- handler

function UIActivityTimeLimitedTaskPanel:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cellNode = listView:NewListViewItem("Cell")
    ---@type UIActivityTimeLimitedTaskCellNode
    local nodeEnv  = CfUtils.GetLuaScr(cellNode, "Game.UI.ActivityMainDialog.UIActivityTimeLimitedTaskCellNode")
    if nodeEnv then
        if self:GetItemShowNum() <= 0 then
            local cellSizeH  = cellNode.CachedRectTransform.rect.height + cellNode.Padding
            self.itemShowNum = math.ceil(listView.ViewPortHeight / cellSizeH)
        end
        if not self.animMapList[index + 1] and index <= self:GetItemShowNum() then
            self.animMapList[index + 1] = true
            nodeEnv:PlayFadeInAnim(index)
        else
            nodeEnv:PlayInitAnim()
        end

        nodeEnv:Refresh(self:GetTaskDt()[index + 1], index)
        nodeEnv:SetBtnCB(function(taskId, nodeEnv)
            local status   = nodeEnv:GetStatus()
            local openType = nodeEnv:GetOpenType()
            local openParameter = nodeEnv:GetOpenParameter()
            if status == Constants.GetStatus.Can then
                self:OnDrawTask(taskId, nodeEnv)
            elseif status == Constants.GetStatus.Not then
                if openType > 0 then
                    local goodsConfMgr = GoodsConfMgr:GetInstance()
                    goodsConfMgr:ExecuteJump(goodsConfMgr:GetJumpModuleRow(openType), {}, 0, false, {url = openParameter})
                    CfUtils.CookieSave(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID, self:GetActivityId())
                end
            else
                GameUtils.Toast("You have already received the reward")
            end

        end)
    end
    return cellNode
end

function UIActivityTimeLimitedTaskPanel:OnDrawTask(taskId, cellEnv)
    GameUtils.Request(Interfaces.ActivityTimeLimitedTaskDraw,
            {activityUuid = self:GetActivityId(), rewardId = taskId},
            function(request, response)
                if checkInt(response.errCode) == 0 then

                    -- update data
                    local data = response.data

                    if checkInt(taskId) <= 0 then
                        self.canTaskMap = {}
                    else
                        self.canTaskMap[checkInt(taskId)] = nil
                    end

                    local cleanIdMap = {}
                    for _, taskId in ipairs(data.drawRewardIds) do
                        cleanIdMap[checkInt(taskId)] = true
                    end

                    for _, taskDt in ipairs(self:GetTaskDt()) do
                        if cleanIdMap[checkInt(taskDt.taskId)] then
                            taskDt.status = Constants.GetStatus.Has
                        end
                    end

                    -- refresh reward
                    local rewardList = checkTable(data.rewards)
                    GoodsUtils.DrawRewards(rewardList, true)
                    CfUtils.DialogOpen(Constants.UITypeIds.UICommonRewardPop, {rewards = rewardList})

                    -- update red
                    if next(self:GetCanIdMap()) == nil then
                        ActivityUtils.UpdateActivityMainRedPointState(self:GetActivityId(), -1)
                    end

                    -- update list
                    if not cellEnv then
                        GameUtils.ReloadData(self.LoopListCell, #self:GetTaskDt())
                    else
                        cellEnv:RefreshStatue()
                    end

                end
            end)
end

return UIActivityTimeLimitedTaskPanel